    # Map each distinct value to the rows in which it appears.
    # (Any occurrence of a value is equivalent: the score depends only on
    # the value, and only the "one cell per row" constraint matters.)
    value_rows = {}
    for r, row in enumerate(grid):
        for v in set(row):
            value_rows.setdefault(v, []).append(r)

    # dp[mask] = best sum after processing some of the values, where mask
    # marks the rows already used. << Each value is processed exactly once
    # (values must be unique), yielding a maximum-weight matching between
    # values and rows with edge weight equal to the value.
    neg = float("-inf")
    size = 1 << n
    dp = [neg] * size
    dp[0] = 0

    for v in sorted(value_rows, reverse=True):
        ndp = dp[:]  # option: skip this value
        for mask in range(size):
            cur = dp[mask]
            if cur < 0:
                continue
            for r in value_rows[v]:
                if not (mask >> r) & 1:
                    nm = mask | (1 << r)
                    cand = cur + v
                    if cand > ndp[nm]:
                        ndp[nm] = cand
        dp = ndp

    return max(dp)
